              r'^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z|([+-](?:[01]\d|2[0-3]):[0-5]\d)))$'),
          format: 'datetime')
      .nullable(),
  'eligibility': conditionGroupSchema.optional(),
  'targetRules': couponTargetRulesSchema.optional(),
  'targetTree': couponTargetTreeSchema.optional(),
  'stacking': couponStackingSchema.optional(),
  'reward': couponRewardSchema.optional(),
}, CouponRule._);

/// 쿠폰 규칙 스냅샷 — 계산에 필요한 값만 담습니다. 결제 시작이 쿠폰을 읽어 이 형태로 결제 세션에 굳히고,
/// 주문 생성·환불 정산은 이 스냅샷만 읽습니다. 결제 도중·주문 뒤 셀러가 쿠폰을 바꿔도 그 주문의 금액은 움직이지 않습니다.
class CouponRule extends ParsedObject {
  /// [CouponRule]을 만듭니다. 검증하지 않으므로 테스트·미리보기 데이터에 사용하십시오.
  CouponRule(
      {required String couponId,
      required String name,
      required String kind,
      required CouponBenefit benefit,
      required CouponConditions conditions,
      required CouponTarget target,
      required String? startsAt,
      required String? endsAt,
      ConditionGroup? eligibility,
      CouponTargetRules? targetRules,
      CouponTargetTree? targetTree,
      CouponStacking? stacking,
      CouponReward? reward})
      : super({
          'couponId': couponId,
          'name': name,
          'kind': kind,
          'benefit': benefit,
          'conditions': conditions,
          'target': target,
          'startsAt': startsAt,
          'endsAt': endsAt,
          if (eligibility != null) 'eligibility': eligibility,
          if (targetRules != null) 'targetRules': targetRules,
          if (targetTree != null) 'targetTree': targetTree,
          if (stacking != null) 'stacking': stacking,
          if (reward != null) 'reward': reward
        });

  CouponRule._(super.json);

  /// JSON을 [couponRuleSchema]로 검증해 만듭니다. 맞지 않으면 [ZodError]를 던집니다.
  factory CouponRule.fromJson(Map<String, Object?> json) => couponRuleSchema.parse(json);

  Map<String, Object?> get _j => jsonOf(this);

  /// 쿠폰 id (`cpn_…`).
  String get couponId => _j['couponId'] as String;

  /// 쿠폰 이름.
  String get name => _j['name'] as String;

  /// 쿠폰 종류. `ORDER`=주문 쿠폰(대상 상품 합계에서 할인), `PRODUCT`=상품 쿠폰(주문상품 한 줄에서 할인), `DELIVERY`=배송비 쿠폰(기본 배송비에서 할인, 지역 추가 배송비 제외).
  String get kind => _j['kind'] as String;

  /// `benefit` 값입니다.
  CouponBenefit get benefit => _j['benefit'] as CouponBenefit;

  /// `conditions` 값입니다.
  CouponConditions get conditions => _j['conditions'] as CouponConditions;

  /// `target` 값입니다.
  CouponTarget get target => _j['target'] as CouponTarget;

  /// 사용 시작 시각(ISO 8601, 시간대 포함). null이면 제한이 없습니다.
  String? get startsAt => _j['startsAt'] as String?;

  /// 사용 종료 시각(ISO 8601, 시간대 포함, 이 시각부터 못 씁니다). null이면 제한이 없습니다.
  String? get endsAt => _j['endsAt'] as String?;

  /// 사용 조건 트리(이슈 #222). 없으면 `conditions`에서 만듭니다. 있으면 이것이 원천이고 `conditions`는 가장 가까운 옛 값입니다.
  ConditionGroup? get eligibility => _j['eligibility'] as ConditionGroup?;

  /// 할인 대상 규칙(이슈 #222). 없으면 `target`·`conditions.stackWithInstantDiscount`에서 만듭니다.
  CouponTargetRules? get targetRules => _j['targetRules'] as CouponTargetRules?;

  /// 할인 대상 트리(이슈 #263). 없으면 `targetRules`(없으면 옛 칸)에서 만듭니다. 있으면 이것이 원천이고 `targetRules`는 가장 가까운 옛 값입니다.
  CouponTargetTree? get targetTree => _j['targetTree'] as CouponTargetTree?;

  /// 중복 사용 정책(이슈 #222). 없으면 종류별 한 장·서로 결합·적립금과 함께.
  CouponStacking? get stacking => _j['stacking'] as CouponStacking?;

  /// 확장 혜택(구간 할인·N+1·적립금 지급). 없으면 `benefit`이 혜택입니다.
  CouponReward? get reward => _j['reward'] as CouponReward?;
}

/// [String] 스키마입니다. 값은 `DUPLICATE_COUPON`·`STACK_LIMIT`·`NOT_STARTED`·`EXPIRED`·`MEMBER_ONLY`·`FIRST_ORDER_ONLY`·`NO_ELIGIBLE_ITEMS`·`MIN_ORDER_AMOUNT`·`LINE_NOT_ELIGIBLE`·`LINE_AMBIGUOUS`·`NO_DISCOUNT`·`CONDITION_NOT_MET`·`NOT_COMBINABLE`입니다.
///
/// 쿠폰을 적용하지 못한 사유.
final ZodEnum couponRejectReasonSchema = z.enum_([
  'DUPLICATE_COUPON',
  'STACK_LIMIT',
  'NOT_STARTED',
  'EXPIRED',
  'MEMBER_ONLY',
  'FIRST_ORDER_ONLY',
  'NO_ELIGIBLE_ITEMS',
  'MIN_ORDER_AMOUNT',
  'LINE_NOT_ELIGIBLE',
  'LINE_AMBIGUOUS',
  'NO_DISCOUNT',
  'CONDITION_NOT_MET',
  'NOT_COMBINABLE'
]);

/// CouponRejectReason 값입니다.
///
/// 값은 `DUPLICATE_COUPON`·`STACK_LIMIT`·`NOT_STARTED`·`EXPIRED`·`MEMBER_ONLY`·`FIRST_ORDER_ONLY`·`NO_ELIGIBLE_ITEMS`·`MIN_ORDER_AMOUNT`·`LINE_NOT_ELIGIBLE`·`LINE_AMBIGUOUS`·`NO_DISCOUNT`·`CONDITION_NOT_MET`·`NOT_COMBINABLE`입니다.
typedef CouponRejectReason = String;

/// 쿠폰 적용 뒤 결제 금액의 하한 — 0원 결제 경로가 없어 이보다 작으면 결제를 시작하지 않습니다(400 `PAYMENT_AMOUNT_TOO_LOW`).
const MIN_PAYMENT_AMOUNT = 100;

/// 계산에 넣는 주문상품 한 줄.
class PricingLine {
  /// [PricingLine]을 만듭니다.
  const PricingLine(
      {required this.lineId,
      required this.productId,
      this.categoryPath,
      required this.quantity,
      required this.baseAmount,
      required this.amount});

  /// 줄 식별자 — 주문서는 항목 순번, 주문은 주문상품 id. 배분 결과가 이 키로 나옵니다.
  final String lineId;

  /// `productId` 값입니다.
  final String productId;

  /// 상품 카테고리 경로(`/조상/…/자신/`). 없으면 카테고리 대상에 걸리지 않습니다.
  final String? categoryPath;

  /// 수량 — 계산에는 쓰지 않습니다(금액이 이미 수량을 반영합니다). 화면·로그용입니다.
  final int quantity;

  /// 즉시할인 전 금액 (정가 단가 × 수량).
  final int baseAmount;

  /// 즉시할인 반영 금액 (할인 단가 × 수량) — 쿠폰 계산의 기준입니다.
  final int amount;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'lineId': lineId,
        'productId': productId,
        if (categoryPath != null) 'categoryPath': categoryPath,
        'quantity': quantity,
        'baseAmount': baseAmount,
        'amount': amount
      };
}

/// 계산에 넣는 쿠폰 한 장.
class PricingCoupon {
  /// [PricingCoupon]을 만듭니다.
  const PricingCoupon(
      {required this.rule,
      this.couponKey,
      this.lineId,
      this.eligibleLineIds,
      this.validFrom,
      this.validUntil,
      this.facts});

  /// `rule` 값입니다.
  final CouponRule rule;

  /// 결과·배분의 키. 생략하면 `rule.couponId`.
  final String? couponKey;

  /// 상품 쿠폰을 걸 줄. 생략하면 계산이 고릅니다 — 줄을 지정한 쿠폰을 먼저 걸고, 나머지는 대상 줄이 적은 쿠폰부터
  /// 할인이 가장 큰 남은 줄(같으면 앞 줄)에 겁니다.
  final String? lineId;

  /// 대상 줄을 이미 정했으면 그 목록 — 환불 정산의 재계산이 씁니다. 주어지면 `target`·즉시할인 조건을 다시
  /// 판정하지 않습니다(주문 뒤 상품의 카테고리·즉시할인이 바뀌어도 주문 시점 대상이 그대로입니다).
  final List<String>? eligibleLineIds;

  /// 발급 쿠폰의 유효 시작·종료 — 쿠폰 사용 기간과 둘 중 좁은 쪽이 적용됩니다.
  final String? validFrom;

  /// `validUntil` 값입니다.
  final String? validUntil;

  /// 이 쿠폰을 판정할 사실 값 — 주문 스냅샷의 값(환불 정산). 주어지면 입력의 `facts`보다 우선합니다.
  /// 결제 시작에서 쓴 구매자·시각 값을 그대로 다시 쓰므로 주문 뒤 바뀐 가입 일수·요일이 결과를 바꾸지 않습니다.
  final CouponFacts? facts;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'rule': rule,
        if (couponKey != null) 'couponKey': couponKey,
        if (lineId != null) 'lineId': lineId,
        if (eligibleLineIds != null) 'eligibleLineIds': eligibleLineIds,
        if (validFrom != null) 'validFrom': validFrom,
        if (validUntil != null) 'validUntil': validUntil,
        if (facts != null) 'facts': facts
      };
}

/// 배송비 쿠폰이 보는 배송비 견적 — `quoteDelivery` 결과의 묶음 내역입니다. 배송비 총액은 묶음의
/// `fee + remoteSurcharge` 합으로 계산합니다(총액을 따로 받으면 묶음과 어긋날 수 있습니다).
class PricingDelivery {
  /// [PricingDelivery]을 만듭니다.
  const PricingDelivery({required this.bundles});

  /// `bundles` 값입니다.
  final List<({String bundleKey, int fee, int remoteSurcharge})> bundles;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {'bundles': bundles};
}

/// 적립금 사용 입력(#93 P3) — 쿠폰 뒤 금액에 씁니다. 규칙은 상점 정책 `use`(`PointUsePolicy`)의 값입니다.
/// 금액은 요청·잔액·최대 비율 중 작은 값을 `unit`으로 내리고, 남는 결제 금액이 100원 아래로 내려가지 않게 줄입니다(적립금 전액 결제는 아직 받지 않습니다).
class PricingPoints {
  /// [PricingPoints]을 만듭니다.
  const PricingPoints({required this.requested, required this.balance, required this.rules});

  /// 구매자가 쓰겠다는 금액.
  final int requested;

  /// 지금 잔액.
  final int balance;

  /// `rules` 값입니다.
  final ({int minBalance, int minAmount, int unit, int maxRatioBp, bool includeDeliveryFee}) rules;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {'requested': requested, 'balance': balance, 'rules': rules};
}

/// 적립금을 쓰지 못한 이유.
typedef PointRejectReason = String;

/// PricingInput 값입니다.
class PricingInput {
  /// [PricingInput]을 만듭니다.
  const PricingInput(
      {required this.lines,
      this.points,
      required this.coupons,
      this.delivery,
      this.firstOrder,
      required this.isMember,
      required this.now,
      this.facts,
      this.ignoreEligibility,
      this.moneyRules});

  /// `lines` 값입니다.
  final List<PricingLine> lines;

  /// 적립금 사용(#93 P3). 없으면 쓰지 않습니다 — 결과는 적립금 이전과 같습니다.
  final PricingPoints? points;

  /// `coupons` 값입니다.
  final List<PricingCoupon> coupons;

  /// 배송비 견적. 없으면 배송비 0으로 계산하고 배송비 쿠폰은 할인할 금액이 없습니다.
  final PricingDelivery? delivery;

  /// 이 상점에서 결제 완료 주문이 없는 회원인지입니다 — 옛 입력입니다. `facts.customer.paidOrderCount`가 없을 때 true면 0으로 읽습니다
  /// (false는 값을 모르는 것으로 둡니다 — 「결제 완료 주문 수 = 0」 규칙은 거짓).
  final bool? firstOrder;

  /// 회원 주문인지입니다.
  final bool isMember;

  /// 사용 기간 판정 시각 — 시각 사실 값(요일·시각)도 여기서 나옵니다.
  final DateTime now;

  /// 구매자 사실 값(이슈 #222) — 사용 조건 트리가 읽습니다. 시각 값을 주지 않으면 `now`에서 만듭니다.
  final CouponFacts? facts;

  /// 사용 기간·회원 전용을 다시 보지 않습니다 — **환불 정산의 재계산 전용입니다.** 그 조건은 결제 시작에서
  /// 이미 통과했습니다. 주문 시각(승인 시각)으로 기간을 다시 보면 결제 시작과 승인 사이에 끝난 쿠폰이 조건을 잃은
  /// 것처럼 보이고, 탈퇴한 회원의 반품이 회원 전용 조건에 떨어집니다. 사용 조건 트리는 쿠폰의 스냅샷 사실 값(`PricingCoupon.facts`)으로
  /// 남은 금액과 함께 다시 평가합니다(트리 일부만 건너뛰면 `or` 트리의 결과가 틀립니다).
  final bool? ignoreEligibility;

  /// 주문 통화의 규칙 값(이슈 #130) — 정률 할인 내림 단위(판매가 단위)와 적립금 사용 뒤 남길 최소 결제액. 생략하면 KRW 규칙입니다.
  /// 금액 입력은 모두 이 통화의 최소 단위입니다.
  final MoneyRules? moneyRules;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'lines': lines,
        if (points != null) 'points': points,
        'coupons': coupons,
        if (delivery != null) 'delivery': delivery,
        if (firstOrder != null) 'firstOrder': firstOrder,
        'isMember': isMember,
        'now': now,
        if (facts != null) 'facts': facts,
        if (ignoreEligibility != null) 'ignoreEligibility': ignoreEligibility,
        if (moneyRules != null) 'moneyRules': moneyRules
      };
}

/// 줄 하나에 들어간 쿠폰별 할인.
class CouponAllocation {
  /// [CouponAllocation]을 만듭니다.
  const CouponAllocation({required this.couponKey, required this.amount});

  /// `couponKey` 값입니다.
  final String couponKey;

  /// `amount` 값입니다.
  final int amount;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {'couponKey': couponKey, 'amount': amount};
}

/// PricingLineResult 값입니다.
class PricingLineResult {
  /// [PricingLineResult]을 만듭니다.
  const PricingLineResult(
      {required this.lineId,
      required this.amount,
      required this.couponDiscount,
      required this.allocations,
      required this.pointAllocation});

  /// `lineId` 값입니다.
  final String lineId;

  /// 즉시할인 반영 금액 (쿠폰 전).
  final int amount;

  /// 이 줄에 들어간 쿠폰 할인 합계 — 상품 쿠폰 + 주문 쿠폰 배분.
  final int couponDiscount;

  /// `allocations` 값입니다.
  final List<CouponAllocation> allocations;

  /// 이 줄에 배분한 사용 적립금(#93 P3). 적립금을 쓰지 않으면 0.
  final int pointAllocation;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'lineId': lineId,
        'amount': amount,
        'couponDiscount': couponDiscount,
        'allocations': allocations,
        'pointAllocation': pointAllocation
      };
}

/// PricingCouponResult 값입니다.
class PricingCouponResult {
  /// [PricingCouponResult]을 만듭니다.
  const PricingCouponResult(
      {required this.couponKey,
      required this.couponId,
      required this.kind,
      required this.applied,
      required this.discount,
      required this.rejectReason,
      required this.lineId,
      required this.eligibleLineIds,
      required this.facts,
      required this.rewardPoint,
      required this.tierIndex});

  /// `couponKey` 값입니다.
  final String couponKey;

  /// `couponId` 값입니다.
  final String couponId;

  /// `kind` 값입니다.
  final CouponKind kind;

  /// `applied` 값입니다.
  final bool applied;

  /// 이 쿠폰의 할인액. 적용하지 못했으면 0.
  final int discount;

  /// `rejectReason` 값입니다.
  final CouponRejectReason? rejectReason;

  /// 상품 쿠폰이 걸린 줄. 그 밖은 null.
  final String? lineId;

  /// 이 쿠폰의 대상 줄 — 판정에 쓴 순서 그대로입니다. 환불 정산이 주문 시점 대상을 되살리는 데 씁니다.
  final List<String> eligibleLineIds;

  /// 판정에 쓴 사실 값 중 이 쿠폰의 사용 조건이 읽은 것 — 주문 스냅샷에 굳힙니다. 읽은 값이 없으면 빈 객체.
  final CouponFacts facts;

  /// 적립금 지급 쿠폰이 구매확정 때 줄 적립금(지금 수량 기준). 그 밖은 0.
  final int rewardPoint;

  /// 구간 할인이 적용한 구간 순번. 그 밖은 null — 환불 정산이 구간이 내려갔는지 봅니다.
  final int? tierIndex;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'couponKey': couponKey,
        'couponId': couponId,
        'kind': kind,
        'applied': applied,
        'discount': discount,
        'rejectReason': rejectReason,
        'lineId': lineId,
        'eligibleLineIds': eligibleLineIds,
        'facts': facts,
        'rewardPoint': rewardPoint,
        'tierIndex': tierIndex
      };
}

/// PricingBundleResult 값입니다.
class PricingBundleResult {
  /// [PricingBundleResult]을 만듭니다.
  const PricingBundleResult({required this.bundleKey, required this.couponDiscount, required this.pointAllocation});

  /// `bundleKey` 값입니다.
  final String bundleKey;

  /// `couponDiscount` 값입니다.
  final int couponDiscount;

  /// 이 배송 묶음에 배분한 사용 적립금(#93 P3).
  final int pointAllocation;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() =>
      {'bundleKey': bundleKey, 'couponDiscount': couponDiscount, 'pointAllocation': pointAllocation};
}

/// PricingResult 값입니다.
class PricingResult {
  /// [PricingResult]을 만듭니다.
  const PricingResult(
      {required this.lines,
      required this.coupons,
      required this.bundles,
      required this.rewardPointAmount,
      required this.productAmount,
      required this.couponDiscountAmount,
      required this.deliveryFee,
      required this.deliveryDiscountAmount,
      required this.pointAmount,
      required this.pointMaxUsable,
      required this.pointAdjustReason,
      required this.pointRejectReason,
      required this.totalAmount});

  /// `lines` 값입니다.
  final List<PricingLineResult> lines;

  /// `coupons` 값입니다.
  final List<PricingCouponResult> coupons;

  /// 배송비 쿠폰의 묶음별 배분.
  final List<PricingBundleResult> bundles;

  /// 적립금 지급 쿠폰의 적립 예정 합계 — 결제 금액에 영향이 없습니다.
  final int rewardPointAmount;

  /// 상품 금액 합 (즉시할인 반영, 쿠폰 전).
  final int productAmount;

  /// 상품·주문 쿠폰 할인 합계.
  final int couponDiscountAmount;

  /// 배송비 (쿠폰 전).
  final int deliveryFee;

  /// 배송비 쿠폰 할인.
  final int deliveryDiscountAmount;

  /// 사용 적립금(#93 P3). 쓰지 않으면 0.
  final int pointAmount;

  /// 지금 쓸 수 있는 최대 적립금 — 주문서 안내값(잔액을 모두 요청했을 때의 금액). 적립금 입력이 없으면 0.
  final int pointMaxUsable;

  /// 요청보다 적게 썼다면 그 이유 — `MIN_PAYMENT`: 남는 결제 금액이 1~99원이라 100원을 남기려고 줄였습니다(전액이면 0원 결제).
  final String? pointAdjustReason;

  /// 요청했지만 쓰지 못했다면 그 이유.
  final PointRejectReason? pointRejectReason;

  /// 결제 금액 = productAmount − couponDiscountAmount + deliveryFee − deliveryDiscountAmount − pointAmount.
  final int totalAmount;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'lines': lines,
        'coupons': coupons,
        'bundles': bundles,
        'rewardPointAmount': rewardPointAmount,
        'productAmount': productAmount,
        'couponDiscountAmount': couponDiscountAmount,
        'deliveryFee': deliveryFee,
        'deliveryDiscountAmount': deliveryDiscountAmount,
        'pointAmount': pointAmount,
        'pointMaxUsable': pointMaxUsable,
        'pointAdjustReason': pointAdjustReason,
        'pointRejectReason': pointRejectReason,
        'totalAmount': totalAmount
      };
}

/// 주문이 받은 쿠폰 한 장 — 주문 시점 규칙과 대상 줄을 굳힌 값입니다(`orders.discounts`의 항목).
/// 환불 정산은 이 값만 읽습니다. 셀러가 쿠폰을 바꾸거나 상품의 카테고리가 바뀌어도 결과가 같습니다.
class AppliedCouponSnapshot {
  /// [AppliedCouponSnapshot]을 만듭니다.
  const AppliedCouponSnapshot(
      {required this.couponKey,
      required this.rule,
      required this.lineId,
      required this.eligibleLineIds,
      required this.discount,
      this.facts});

  /// `couponKey` 값입니다.
  final String couponKey;

  /// `rule` 값입니다.
  final CouponRule rule;

  /// 상품 쿠폰이 걸린 주문상품 id. 그 밖은 null.
  final String? lineId;

  /// 주문 시점 대상 주문상품 id — 주문서 항목 순서 그대로입니다.
  final List<String> eligibleLineIds;

  /// 주문 시점 할인액.
  final int discount;

  /// 주문 시점 사실 값(이슈 #222) — 사용 조건 트리가 읽은 구매자·시각 값. 없으면 빈 값(옛 주문).
  final CouponFacts? facts;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'couponKey': couponKey,
        'rule': rule,
        'lineId': lineId,
        'eligibleLineIds': eligibleLineIds,
        'discount': discount,
        if (facts != null) 'facts': facts
      };
}

/// 정산이 보는 주문상품 한 줄 — 이번 취소를 **반영한 뒤**의 활성 수량입니다.
class CouponSettlementLine {
  /// [CouponSettlementLine]을 만듭니다.
  const CouponSettlementLine(
      {required this.lineId,
      required this.productId,
      required this.quantity,
      required this.activeQuantity,
      required this.totalPrice,
      required this.allocations});

  /// `lineId` 값입니다.
  final String lineId;

  /// `productId` 값입니다.
  final String productId;

  /// `quantity` 값입니다.
  final int quantity;

  /// 남은 활성 수량 (이번 취소 반영 뒤).
  final int activeQuantity;

  /// 주문상품 금액 (즉시할인 반영 단가 × 전체 수량, 쿠폰 전).
  final int totalPrice;

  /// 주문 시점 쿠폰별 배분.
  final List<CouponAllocation> allocations;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'lineId': lineId,
        'productId': productId,
        'quantity': quantity,
        'activeQuantity': activeQuantity,
        'totalPrice': totalPrice,
        'allocations': allocations
      };
}

/// 쿠폰 한 장의 정산 누적 — `orders.coupon_settlements[couponKey]`.
class CouponSettlementState {
  /// [CouponSettlementState]을 만듭니다.
  const CouponSettlementState({required this.charged, required this.waived});

  /// 지금까지 환불에서 뺀 조건 미달 차감 (되돌린 금액을 뺀 값).
  final int charged;

  /// 판매자 귀책·정책 꺼짐으로 받지 않기로 한 미달분 — 뒤의 환불이 다시 청구하지 않게 남깁니다.
  final int waived;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {'charged': charged, 'waived': waived};
}

/// CouponSettlementInput 값입니다.
class CouponSettlementInput {
  /// [CouponSettlementInput]을 만듭니다.
  const CouponSettlementInput(
      {required this.coupons,
      required this.lines,
      required this.settlements,
      required this.shortfallCharge,
      required this.sellerFault,
      required this.chargeableAmount});

  /// `coupons` 값입니다.
  final List<AppliedCouponSnapshot> coupons;

  /// `lines` 값입니다.
  final List<CouponSettlementLine> lines;

  /// `settlements` 값입니다.
  final Map<String, ({int? charged, int? waived})?> settlements;

  /// 상점 환불 정책 `couponShortfallCharge`.
  final bool shortfallCharge;

  /// 판매자 귀책(직권취소, 불량·오배송 반품) — 미달분을 청구하지 않습니다.
  final bool sellerFault;

  /// 이번 환불에서 실제로 뺄 수 있는 금액 — 차감의 상한입니다. 넘겨 차감하면 환불은 0원으로 잘리는데 기록에는
  /// 전액이 남아, 뒤에 되돌릴 때 받지 않은 돈을 돌려줍니다(배송비 미달 차감의 `chargeableAmount`와 같은 이유).
  final int chargeableAmount;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'coupons': coupons,
        'lines': lines,
        'settlements': settlements,
        'shortfallCharge': shortfallCharge,
        'sellerFault': sellerFault,
        'chargeableAmount': chargeableAmount
      };
}

/// CouponSettlementEntry 값입니다.
class CouponSettlementEntry {
  /// [CouponSettlementEntry]을 만듭니다.
  const CouponSettlementEntry(
      {required this.couponKey,
      required this.allocatedRemaining,
      required this.recomputed,
      required this.target,
      required this.charge,
      required this.refund,
      required this.waive,
      required this.next});

  /// `couponKey` 값입니다.
  final String couponKey;

  /// 남은 주문상품에 배분된 할인.
  final int allocatedRemaining;

  /// 남은 주문상품으로 다시 계산한 할인 — 쿠폰 조건을 잃었으면 0.
  final int recomputed;

  /// 누적 미달분 목표 = 조건을 잃었으면 `allocatedRemaining`, 차액 정산 쿠폰은 `allocatedRemaining − recomputed`(음수면 더 돌려줍니다), 아니면 0.
  final int target;

  /// `charge` 값입니다.
  final int charge;

  /// `refund` 값입니다.
  final int refund;

  /// `waive` 값입니다.
  final int waive;

  /// `next` 값입니다.
  final CouponSettlementState next;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {
        'couponKey': couponKey,
        'allocatedRemaining': allocatedRemaining,
        'recomputed': recomputed,
        'target': target,
        'charge': charge,
        'refund': refund,
        'waive': waive,
        'next': next
      };
}

/// CouponSettlementResult 값입니다.
class CouponSettlementResult {
  /// [CouponSettlementResult]을 만듭니다.
  const CouponSettlementResult({required this.chargeAmount, required this.refundAmount, required this.entries});

  /// 이번 환불에서 뺄 금액 — 조건 미달 차감.
  final int chargeAmount;

  /// 이번 환불에 더할 금액 — 앞선 환불에서 뺀 차감을 되돌린 몫.
  final int refundAmount;

  /// `entries` 값입니다.
  final List<CouponSettlementEntry> entries;

  /// JSON으로 바꿉니다.
  Map<String, Object?> toJson() => {'chargeAmount': chargeAmount, 'refundAmount': refundAmount, 'entries': entries};
}

/// NO_COUPON_SETTLEMENT 값입니다.
const NO_COUPON_SETTLEMENT = <String, Object?>{'chargeAmount': 0, 'refundAmount': 0, 'entries': <Object?>[]};
